<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content publishx-scope"><div class="publishx-page-header"><div><h3><?php echo _l('publishx_media_library'); ?></h3><p>This library shows only files stored by the Blogging module.</p></div></div><div class="panel_s"><div class="panel-body"><div class="publishx-upload-card"><?php echo form_open_multipart(admin_url('publishx/upload_media')); ?><div class="row"><div class="col-md-9"><input type="file" name="blogging_media" class="form-control" accept="image/*,video/mp4,video/webm" required></div><div class="col-md-3"><button class="btn btn-primary btn-block"><i class="fa fa-upload"></i> Upload to Blogging Library</button></div></div><?php echo form_close(); ?></div><hr><div class="publishx-media-grid"><?php foreach($media as $m){?><div class="publishx-media-item"><?php if($m['type']==='image'){?><img src="<?php echo html_escape($m['url']); ?>"><?php }else{?><video controls src="<?php echo html_escape($m['url']); ?>"></video><?php }?><input class="form-control input-sm" value="<?php echo html_escape($m['url']); ?>" readonly onclick="this.select()"><small><?php echo html_escape($m['name']); ?></small></div><?php }?></div><?php if(empty($media)){?><div class="alert alert-info">The Blogging media folder is empty.</div><?php }?></div></div></div></div><?php init_tail(); ?></body></html>